#!/usr/bin/env bash
set -euo pipefail

# ============================================================================
# Fase 8c -- Geocodificación automática de pedidos importados.
#
# Causa detectada: el Planificador mostraba pedidos sin coordenadas porque
# el sistema SÍ tiene geocodificación automática (OpenRouteService, la misma
# API que ya usa el motor de rutas), pero solo estaba conectada al alta/
# edición manual de un punto de entrega desde el formulario -- los tres
# caminos que realmente crean pedidos en volumen (import Excel de pedidos,
# bridge ERP Claud, import de maestro de clientes) creaban el punto de
# entrega directamente sin pasar por ahí, así que nunca llegaban a tener
# lat/lng aunque la dirección estuviera completa.
#
# Qué trae este script:
#  1. Un nuevo fichero (delivery-points.service.ts) con la geocodificación
#     "best effort" centralizada, para reutilizarla desde los tres sitios.
#  2. Los tres importadores ahora geocodifican automáticamente cada punto de
#     entrega nuevo justo DESPUÉS de confirmar su transacción (nunca dentro
#     de ella, para no tener una llamada de red externa bloqueando una
#     transacción de base de datos).
#  3. Un script de backfill (geocode-backfill.ts) para rellenar YA los puntos
#     de entrega existentes que se quedaron sin coordenadas -- incluidos los
#     14 pedidos de Getafe que aparecían "sin coordenadas" en el Planificador.
#
# Es aditivo: si no hay dirección reconocible, si ORS no responde o si se
# agota la cuota, el pedido se sigue creando exactamente igual que hasta
# ahora (solo se queda sin coordenadas) -- nunca bloquea una importación.
#
# Después de aplicar este script y hacer el deploy, ejecuta UNA VEZ (desde
# la carpeta backend/) para desatascar el histórico ya cargado:
#
#   npx tsx src/scripts/geocode-backfill.ts
#
# ============================================================================

TARGET_DIR="${1:-.}"
cd "$TARGET_DIR"

echo "Aplicando Fase 8c (geocodificación automática) sobre: $(pwd)"
echo

FILES_APPLIED=(
  "backend/src/modules/delivery-points/delivery-points.service.ts"
  "backend/src/scripts/geocode-backfill.ts"
  "backend/src/modules/orders/orders-excel-import.service.ts"
  "backend/src/modules/integrations/erpclaud/erpclaud.service.ts"
  "backend/src/modules/customers/customer-master-import.service.ts"
)

echo "-> backend/src/modules/delivery-points/delivery-points.service.ts"
mkdir -p "$(dirname "backend/src/modules/delivery-points/delivery-points.service.ts")"
base64 -d > "backend/src/modules/delivery-points/delivery-points.service.ts" <<'B64EOF_backend_src_modules_delivery_points_delivery_points_service_ts'

B64EOF_backend_src_modules_delivery_points_delivery_points_service_ts

echo "-> backend/src/scripts/geocode-backfill.ts"
mkdir -p "$(dirname "backend/src/scripts/geocode-backfill.ts")"
base64 -d > "backend/src/scripts/geocode-backfill.ts" <<'B64EOF_backend_src_scripts_geocode_backfill_ts'

B64EOF_backend_src_scripts_geocode_backfill_ts

echo "-> backend/src/modules/orders/orders-excel-import.service.ts"
mkdir -p "$(dirname "backend/src/modules/orders/orders-excel-import.service.ts")"
base64 -d > "backend/src/modules/orders/orders-excel-import.service.ts" <<'B64EOF_backend_src_modules_orders_orders_excel_import_service_ts'

B64EOF_backend_src_modules_orders_orders_excel_import_service_ts

echo "-> backend/src/modules/integrations/erpclaud/erpclaud.service.ts"
mkdir -p "$(dirname "backend/src/modules/integrations/erpclaud/erpclaud.service.ts")"
base64 -d > "backend/src/modules/integrations/erpclaud/erpclaud.service.ts" <<'B64EOF_backend_src_modules_integrations_erpclaud_erpclaud_service_ts'

B64EOF_backend_src_modules_integrations_erpclaud_erpclaud_service_ts

echo "-> backend/src/modules/customers/customer-master-import.service.ts"
mkdir -p "$(dirname "backend/src/modules/customers/customer-master-import.service.ts")"
base64 -d > "backend/src/modules/customers/customer-master-import.service.ts" <<'B64EOF_backend_src_modules_customers_customer_master_import_service_ts'

B64EOF_backend_src_modules_customers_customer_master_import_service_ts

echo
echo "Fase 8c aplicada correctamente."
echo "Ficheros nuevos/actualizados:"
for f in "${FILES_APPLIED[@]}"; do
  echo "  - $f"
done
echo
echo "Recuerda ejecutar el backfill una vez, tras el deploy, desde backend/:"
echo "  npx tsx src/scripts/geocode-backfill.ts"
